package clientgen

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const goHeader = `// Code generated by melange. DO NOT EDIT.
//
// melange version: v0.9.0
// source: schemas/schema.fga

package authz
`

const tsHeader = `/**
 * Generated by melange. DO NOT EDIT.
 *
 * melange version: v0.9.0
 * source: ../schemas/schema.fga
 */

export const ObjectTypes = {};
`

// The header's version and source lines are what a file records about its
// generation, not what it holds; everything after the header is kept.
func TestNormalize_StripsTraceHeader(t *testing.T) {
	bare := func(s string) string {
		var out []string
		for _, line := range strings.Split(s, "\n") {
			if !strings.Contains(line, "melange version: ") && !strings.Contains(line, "source: ") {
				out = append(out, line)
			}
		}
		return strings.Join(out, "\n")
	}
	for name, content := range map[string]string{"go": goHeader, "typescript": tsHeader} {
		t.Run(name, func(t *testing.T) {
			if got, want := string(Normalize([]byte(content))), strings.TrimRight(bare(content), "\n"); got != want {
				t.Errorf("Normalize:\n%s\nwant:\n%s", got, want)
			}
			if !bytes.Equal(Normalize([]byte(content)), Normalize([]byte(bare(content)))) {
				t.Error("a file generated without the trace lines differs")
			}
			crlf := strings.ReplaceAll(content, "\n", "\r\n")
			if !bytes.Equal(Normalize([]byte(crlf)), Normalize([]byte(content))) {
				t.Error("a CRLF checkout differs")
			}
			if !bytes.Equal(Normalize([]byte(content+"\n\n  ")), Normalize([]byte(content))) {
				t.Error("trailing whitespace at the end differs")
			}
		})
	}

	body := goHeader + "\n// source: kept, it is in the code\nconst X = 1\n"
	if !strings.Contains(string(Normalize([]byte(body))), "// source: kept") {
		t.Error("a source: line after the header was dropped")
	}
	if strings.Contains(string(Normalize([]byte(body))), "schemas/schema.fga") {
		t.Error("the header's source line was kept")
	}
}

func TestHeaderVersion(t *testing.T) {
	for _, tc := range []struct{ content, want string }{
		{goHeader, "v0.9.0"},
		{tsHeader, "v0.9.0"},
		{strings.ReplaceAll(goHeader, "\n", "\r\n"), "v0.9.0"},
		{"// Code generated by melange. DO NOT EDIT.\n//\n\npackage authz\n", ""},
		{"package authz\n// melange version: v1\n", ""},
	} {
		if got := HeaderVersion([]byte(tc.content)); got != tc.want {
			t.Errorf("HeaderVersion(%q) = %q, want %q", tc.content, got, tc.want)
		}
	}
}

func TestCompareFiles(t *testing.T) {
	write := func(t *testing.T, dir string, files map[string]string) {
		t.Helper()
		for name, content := range files {
			if err := os.WriteFile(filepath.Join(dir, name), []byte(content), 0o600); err != nil {
				t.Fatal(err)
			}
		}
	}
	gen := "// Code generated by melange. DO NOT EDIT.\n//\n\npackage authz\n\nconst A = 1\nconst B = 2\n"

	t.Run("identical up to the header", func(t *testing.T) {
		dir := t.TempDir()
		write(t, dir, map[string]string{"schema_gen.go": strings.Replace(gen, "//\n\n", "//\n// melange version: v0.1.0\n// source: x.fga\n\n", 1), "other.go": "package authz\n"})
		drift, err := CompareFiles(map[string][]byte{"schema_gen.go": []byte(gen)}, dir)
		if err != nil || len(drift) != 0 {
			t.Fatalf("drift %+v, err %v", drift, err)
		}
	})

	t.Run("missing", func(t *testing.T) {
		drift, err := CompareFiles(map[string][]byte{"schema_gen.go": []byte(gen)}, t.TempDir())
		if err != nil || len(drift) != 1 || drift[0] != (FileDrift{File: "schema_gen.go", Status: "missing"}) {
			t.Fatalf("drift %+v, err %v", drift, err)
		}
	})

	t.Run("body differs at its line", func(t *testing.T) {
		dir := t.TempDir()
		onDisk := strings.Replace(gen, "//\n\n", "//\n// melange version: v0.1.0\n\n", 1)
		write(t, dir, map[string]string{"schema_gen.go": strings.Replace(onDisk, "B = 2", "B = 3", 1)})
		drift, err := CompareFiles(map[string][]byte{"schema_gen.go": []byte(gen)}, dir)
		if err != nil {
			t.Fatal(err)
		}
		// Line 7 of the normalized file is line 8 on disk: the version line
		// above it is not compared, but it is in the file.
		want := FileDrift{File: "schema_gen.go", Status: "differs", Line: 8, OnDiskVersion: "v0.1.0"}
		if len(drift) != 1 || drift[0] != want {
			t.Fatalf("drift %+v, want %+v", drift, want)
		}
	})

	t.Run("a shorter file differs after its last line", func(t *testing.T) {
		dir := t.TempDir()
		write(t, dir, map[string]string{"schema_gen.go": strings.TrimSuffix(gen, "const B = 2\n")})
		drift, err := CompareFiles(map[string][]byte{"schema_gen.go": []byte(gen)}, dir)
		if err != nil || len(drift) != 1 || drift[0].Line != 7 {
			t.Fatalf("drift %+v, err %v", drift, err)
		}
	})

	t.Run("typescript, only sql.ts differs", func(t *testing.T) {
		dir := t.TempDir()
		want := map[string][]byte{
			"types.ts":  []byte(tsHeader),
			"schema.ts": []byte("/**\n * Generated by melange. DO NOT EDIT.\n */\n\nexport {};\n"),
			"sql.ts":    []byte("/**\n * Generated by melange. DO NOT EDIT.\n */\n\nexport const AccessibleFunctions = {};\n"),
			"index.ts":  []byte("export * from './types.js';\n"),
		}
		files := make(map[string]string)
		for name, content := range want {
			files[name] = string(content)
		}
		files["sql.ts"] = strings.Replace(files["sql.ts"], "{}", "{ a: 1 }", 1)
		write(t, dir, files)
		drift, err := CompareFiles(want, dir)
		if err != nil {
			t.Fatal(err)
		}
		if len(drift) != 1 || drift[0].File != "sql.ts" || drift[0].Line != 5 || drift[0].OnDiskVersion != "" {
			t.Fatalf("drift %+v", drift)
		}
	})
}
